--Q9 are customers who are repeat buyer (moree 5 previous puchase ) also subscribe
SELECT "Subscription Status",
       COUNT("Customer ID") AS repeat_buyers
FROM customer
WHERE "Previous Purchases" > 5
GROUP BY "Subscription Status";
---column name finding 
SELECT column_name
FROM information_schema.columns
WHERE table_name = 'customer';

--Q10  what is the revenue constribution of each age grp ?
SELECT
    CASE
        WHEN "Age" < 25 THEN 'Under 25'
        WHEN "Age" BETWEEN 25 AND 34 THEN '25-34'
        WHEN "Age" BETWEEN 35 AND 44 THEN '35-44'
        ELSE '45+'
    END AS age_group,
    ROUND(
        SUM("Purchase Amount (USD)") * 100.0 /
        (SELECT SUM("Purchase Amount (USD)") FROM customer),
        2
    ) AS revenue_contribution
FROM customer
GROUP BY age_group
ORDER BY revenue_contribution DESC;